// Verify Cryptographic HMAC Signature
const crypto = require('crypto');
const secret = $env.N8N_HMAC_SECRET || 'n8n-default-secret';
const rawBody = JSON.stringify($json.body);
const signature = $headers['x-apex-signature'];

const expected = crypto.createHmac('sha256', secret).update(rawBody).digest('hex');
if (signature !== expected) {
  throw new Error('HMAC signature verification failed');
}

return [{
  json: {
    tenant_id: $json.body.tenant_id,
    client_email: $json.body.client_email,
    raw_api_key: $json.body.raw_api_key,
    usd_funded: $json.body.usd_funded,
    cu_minted: $json.body.cu_minted,
    cluster_preference: $json.body.cluster_preference
  }
}];
